<?php declare(strict_types=1);if(PHP_SAPI!=='cli')exit(1);require dirname(__DIR__).'/app/bootstrap.php';use StudPulse\Config;use StudPulse\Database\DB;function existsInSchema(string$table,?string$column=null):bool{return$column===null?DB::one('SELECT 1 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?',[$table])!==null:DB::one('SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name=? AND column_name=?',[$table,$column])!==null;}function createTables(array$tables):void{$schema=file_get_contents(ROOT.'/database/schema.sql');foreach($tables as$table){if(existsInSchema($table))continue;$pattern='/^CREATE TABLE `'.preg_quote($table,'/').'` \(\R.*?^\) ENGINE=InnoDB[^\r\n]*;/ms';if($schema===false||!preg_match($pattern,$schema,$match)){throw new RuntimeException("Не найдено определение $table в database/schema.sql.");}DB::run($match[0]);echo"Создана таблица $table.\n";}}try{$lock='sp:mail-schema:'.substr(hash('sha256',(string)DB::one('SELECT DATABASE() AS name')['name']),0,42);if(!(int)DB::one('SELECT GET_LOCK(?,10) AS acquired',[$lock])['acquired']){fwrite(STDERR,"Другое обновление схемы ещё выполняется.\n");exit(1);}try{if(!existsInSchema('user_sessions')||!existsInSchema('notifications')||!existsInSchema('user_profiles')){throw new RuntimeException('Сначала импортируйте database/schema.sql в пустую базу.');}$barsTables=['bars_auth_flows'=>'CREATE TABLE IF NOT EXISTS bars_auth_flows (
                token_hash CHAR(64) NOT NULL,
                browser_hash CHAR(64) NOT NULL,
                ciphertext MEDIUMTEXT NOT NULL,
                expires_at DATETIME(6) NOT NULL,
                PRIMARY KEY (token_hash),
                KEY expires_at (expires_at)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci','bars_accounts'=>'CREATE TABLE IF NOT EXISTS bars_accounts (
                login_key CHAR(64) NOT NULL,
                login VARCHAR(100) NOT NULL,
                user_id CHAR(36) NOT NULL,
                password_hash VARCHAR(255) NOT NULL,
                verified_at DATETIME(6) NOT NULL,
                PRIMARY KEY (login_key),
                KEY user_id (user_id)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci',];foreach($barsTables as$table=>$definition){if(existsInSchema($table))continue;DB::run($definition);echo"Создана таблица $table.\n";}if(!existsInSchema('user_profiles','avatar_jpeg')){DB::run('ALTER TABLE user_profiles ADD COLUMN avatar_jpeg MEDIUMBLOB DEFAULT NULL');echo"Добавлено хранение фото профиля.\n";}if(!existsInSchema('user_profiles','avatar_version')){DB::run('ALTER TABLE user_profiles ADD COLUMN avatar_version CHAR(36) DEFAULT NULL');}if(existsInSchema('group_rating_profiles')&&!existsInSchema('group_rating_profiles','absence_count')){DB::run('ALTER TABLE group_rating_profiles ADD COLUMN absence_count INT UNSIGNED DEFAULT NULL');}if(existsInSchema('group_rating_profiles')&&!existsInSchema('group_rating_profiles','attendance_observed_at')){DB::run('ALTER TABLE group_rating_profiles ADD COLUMN attendance_observed_at DATETIME DEFAULT NULL');}if(existsInSchema('drive_sync_runs')&&!existsInSchema('drive_sync_runs','started_at')){DB::run('ALTER TABLE drive_sync_runs ADD COLUMN started_at DATETIME(6) DEFAULT NULL AFTER created_at');}if(existsInSchema('drive_sync_roots')){createTables(['drive_sync_folders','drive_sync_repairs']);if(!existsInSchema('drive_sync_roots','tree_ready'))DB::run('ALTER TABLE drive_sync_roots ADD COLUMN tree_ready TINYINT(1) NOT NULL DEFAULT 0');if(!existsInSchema('materials','drive_root_id'))DB::run('ALTER TABLE materials ADD COLUMN drive_root_id CHAR(36) DEFAULT NULL,
                ADD COLUMN drive_parent_id VARCHAR(160) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
                ADD KEY material_drive_folder (drive_root_id,drive_parent_id)');if(!existsInSchema('drive_sync_events','error_code'))DB::run('ALTER TABLE drive_sync_events ADD COLUMN error_code VARCHAR(60) DEFAULT NULL');if(!existsInSchema('drive_sync_versions','remote_id'))DB::run('ALTER TABLE drive_sync_versions
                ADD COLUMN remote_id VARCHAR(160) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
                ADD COLUMN revision_id VARCHAR(160) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL');}if(existsInSchema('push_subscriptions')&&!existsInSchema('push_subscriptions','last_mail_success_at')){if(!(int)DB::one("SELECT GET_LOCK('studpulse:notifications',90) AS acquired")['acquired']){fwrite(STDERR,"Планировщик занят. Повторите обновление схемы после текущего прохода.\n");exit(1);}try{DB::run('ALTER TABLE push_subscriptions ADD COLUMN last_mail_success_at DATETIME(6) DEFAULT NULL');DB::run('UPDATE push_subscriptions SET last_mail_success_at=last_success_at
                    WHERE last_mail_success_at IS NULL AND last_success_at IS NOT NULL');echo"Добавлена отдельная отметка доставки почтовых Push.\n";}finally{DB::run("SELECT RELEASE_LOCK('studpulse:notifications')");}}if(existsInSchema('push_subscriptions'))createTables(['push_deliveries']);if(!Config::bool('MPEI_MAIL_ENABLED'))return;if(!existsInSchema('mpei_mail_connections')){DB::run("CREATE TABLE mpei_mail_connections (
                session_id CHAR(36) NOT NULL PRIMARY KEY,
                generation CHAR(36) NOT NULL,
                ciphertext TEXT NOT NULL,
                expires_at DATETIME(6) NOT NULL,
                poll_enabled TINYINT(1) NOT NULL DEFAULT 0,
                uid_validity BIGINT UNSIGNED NOT NULL,
                uid_next BIGINT UNSIGNED NOT NULL,
                last_synced_at DATETIME(6) DEFAULT NULL,
                next_check_at DATETIME(6) NOT NULL,
                KEY mpei_mail_due (poll_enabled,next_check_at),
                KEY mpei_mail_expiry (expires_at),
                CONSTRAINT mpei_mail_session FOREIGN KEY (session_id) REFERENCES user_sessions(id) ON DELETE CASCADE
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci");echo"Создана таблица mpei_mail_connections.\n";}if(!existsInSchema('mpei_mail_connections','last_synced_at')){DB::run('ALTER TABLE mpei_mail_connections ADD COLUMN last_synced_at DATETIME(6) DEFAULT NULL');echo"Добавлена колонка mpei_mail_connections.last_synced_at.\n";}if(!existsInSchema('notifications','received_at')){DB::run('ALTER TABLE notifications ADD COLUMN received_at DATETIME(6) DEFAULT NULL');echo"Добавлена колонка notifications.received_at.\n";}createTables(['mpei_mail_folders','mpei_mail_messages','mpei_mail_drafts','mpei_mail_draft_parts']);if(existsInSchema('mpei_mail_cache'))DB::run('DELETE FROM mpei_mail_cache WHERE expires_at<=UTC_TIMESTAMP(6)');echo"Почта МЭИ: схема актуальна.\n";}finally{DB::run('SELECT RELEASE_LOCK(?)',[$lock]);}}catch(PDOException$error){fprintf(STDERR,"Обновление схемы не выполнено (MySQL %d). Проверьте подключение и права CREATE/ALTER.\n",(int)($error->errorInfo[1]??0));exit(1);}catch(RuntimeException$error){fwrite(STDERR,"Проверьте параметры MySQL и наличие базовой схемы database/schema.sql.\n");exit(1);}